// ─── India 36 States & Union Territories Climate Intelligence Data ──────────
// Official Data Sources:
// - Temperature: India Meteorological Department (IMD) Annual Mean Surface Air Temperature (2023)
// - Rainfall: IMD Hydromet Division Annual State-wise Rainfall Statistics (2023)
// - CO2 Emissions: GHG Platform India & NITI Aayog India Climate & Energy Dashboard (ICED) (2020)
// Geometry: Official Survey of India / geoBoundaries ADM1 alignment

export interface StateClimateRecord {
  id: string;
  name: string;
  code: string;
  temperature: number; // °C
  rainfall: number;    // mm
  co2: number;         // Mt CO₂e (Million Tonnes)
  region: 'Northern' | 'Southern' | 'Western' | 'Eastern' | 'Central' | 'Northeastern' | 'Islands';
  path: string;
  center: { x: number; y: number };
}

export type IndicatorType = 'temperature' | 'rainfall' | 'co2';

export interface IndicatorMeta {
  key: IndicatorType;
  label: string;
  unit: string;
  year: string;
  agency: string;
  description: string;
  format: (val: number) => string;
  min: number;
  max: number;
  colorStops: { pct: number; color: string; label: string }[];
}

