export function getStateColor(indicator: IndicatorType, value: number): string {
  const meta = INDICATOR_METAS[indicator];
  const ratio = Math.max(0, Math.min(1, (value - meta.min) / (meta.max - meta.min)));

  if (indicator === 'temperature') {
    // Cold blue -> Sky -> Amber -> Orange -> Crimson
    if (ratio < 0.35) return interpolateColor('#38bdf8', '#0ea5e9', ratio / 0.35);
    if (ratio < 0.65) return interpolateColor('#0ea5e9', '#f59e0b', (ratio - 0.35) / 0.3);
    if (ratio < 0.85) return interpolateColor('#f59e0b', '#ea580c', (ratio - 0.65) / 0.2);
    return interpolateColor('#ea580c', '#dc2626', (ratio - 0.85) / 0.15);
  }

  if (indicator === 'rainfall') {
    // Sand gold -> Cyan -> Emerald green
    if (ratio < 0.25) return interpolateColor('#d97706', '#22d3ee', ratio / 0.25);
    if (ratio < 0.5) return interpolateColor('#22d3ee', '#06b6d4', (ratio - 0.25) / 0.25);
    if (ratio < 0.75) return interpolateColor('#06b6d4', '#10b981', (ratio - 0.5) / 0.25);
    return interpolateColor('#10b981', '#047857', (ratio - 0.75) / 0.25);
  }

  // CO2: Emerald green -> Amber -> Orange -> Red
  if (ratio < 0.2) return interpolateColor('#10b981', '#14b8a6', ratio / 0.2);
  if (ratio < 0.45) return interpolateColor('#14b8a6', '#f59e0b', (ratio - 0.2) / 0.25);
  if (ratio < 0.75) return interpolateColor('#f59e0b', '#f97316', (ratio - 0.45) / 0.3);
  return interpolateColor('#f97316', '#ef4444', (ratio - 0.75) / 0.25);
}

function interpolateColor(color1: string, color2: string, factor: number): string {
  const c1 = hexToRgb(color1);
  const c2 = hexToRgb(color2);
  const f = Math.max(0, Math.min(1, factor));
  const r = Math.round(c1.r + f * (c2.r - c1.r));
  const g = Math.round(c1.g + f * (c2.g - c1.g));
  const b = Math.round(c1.b + f * (c2.b - c1.b));
  return `rgb(${r}, ${g}, ${b})`;
}

function hexToRgb(hex: string): { r: number; g: number; b: number } {
  const sanitized = hex.replace('#', '');
  return {
    r: parseInt(sanitized.substring(0, 2), 16),
    g: parseInt(sanitized.substring(2, 4), 16),
    b: parseInt(sanitized.substring(4, 6), 16),
  };
}
